{
  "diagnosis": "The function `idempotency_key` fails to handle case-insensitive headers properly, leading to assertion failures in the test case `train-header-lowercase`.",
  "expected_effect": "The function should normalize the idempotency key to be case-insensitive, ensuring that headers like `Idempotency-Key` or `idempotency-key` are treated identically.",
  "schema_version": "exp002-diagnosis-update/v1",
  "updates": {
    "harness.py": "def idempotency_key(headers) -> str:\n    \"\"\"Return a normalized idempotency key.\"\"\"\n    key = headers.get(\"Idempotency-Key\")\n    if not key:\n        raise ValueError(\"Missing idempotency key\")\n    return key.strip().lower()"
  }
}

